function referenceCatalogue(step,name='Scotsman, The/Scotland on Sunday (Scotland)'){const cols=sourceColumns().map(({index,...column})=>({...column,visible:Number(column.visible),searchable:Number(column.searchable),sortable:Number(column.sortable)}));cols[0].template='/apps/news/browse-pub?p=UKNB&t=__1__&action=browse';const {document}=parseHTML('<div class="nbcore-react-browse-container" id="catalogue"></div><script>jQuery.extend(Drupal.settings,'+JSON.stringify({nbcore_react_browse__catalogue:{config:{},cols,rows:[[name,step,'1998 - Current','Scotland','Newspaper','Text','English']]}})+');</script>');return cataloguePropsEvidence(document,'https://infoweb.newsbank.com/apps/news/source-list?p=UKNB');}

test('owner namespace-local identifiers and one encoded exact source name mirror the backend six-field receipt',async()=>{
 const name='Scotsman, The/Scotland on Sunday (Scotland)',encoded=encodeURIComponent(name).replace(/%20/g,'+');for(const id of ['ABCDEF0123456789','123456789012','qwertyuiopasdfghjklzxcvbnmqwertyuiopasdfgh'])for(const suffix of ['', '!'+name,'!'+encoded]){const input=referenceCatalogue('pubname:'+id+suffix),source=input.sourceDescriptors.sources[0];assert.equal(source.browse.status,'available');assert.equal(Object.keys(source.browse.referenceStructure).length,6);const {value,h}=await exportCatalogue(input);assert.deepEqual(value.sourceDescriptors,input.sourceDescriptors);assert.equal(value.sourceDescriptors.sources[0].browse.referenceStructure.identifierLength,id.length);assert.equal(value.sourceDescriptors.sources[0].browse.referenceStructure.nameEncoding,suffix?(suffix==='!'+name?'literal':'form-encoded'):'none');assert.equal(value.sourceDescriptors.sources[0].browse.referenceStructure.failureCode,'none');assert.equal(h.calls.length,1);assert.equal(h.document.querySelectorAll('#native-source-results a').length,0);assert.doesNotMatch(JSON.stringify(source.browse.referenceStructure),new RegExp(id));}
});

test('owner reference receipt rejects malformed fields, wrong context and false success receipts',async()=>{
 const input=referenceCatalogue('pubname:ABCDEF0123456789'),base=input.sourceDescriptors.sources[0].browse.referenceStructure;
 for(const change of [{namespace:'session'},{identifierKind:'PRIVATE'},{identifierLength:81},{identifierLength:0},{hasName:true},{nameEncoding:'PRIVATE'},{failureCode:'PRIVATE'},{rawIdentifier:'PRIVATE_ID'}]){const raw=structuredClone(input);Object.assign(raw.sourceDescriptors.sources[0].browse.referenceStructure,change);const {value}=await exportCatalogue(raw);assert.deepEqual(value.sourceDescriptors.sources,[]);assert.doesNotMatch(JSON.stringify(value),/PRIVATE_ID|"namespace":"session"/);}
 const raw=sourceCatalogue();raw.sourceDescriptors.sources[0].browse.referenceStructure=base;const invalid=await exportCatalogue(raw);assert.deepEqual(invalid.value.sourceDescriptors.sources,[]);
 for(const step of ['pubname:tokenABCDEF','pubname:ABCDEF0123456789!Other Newspaper','pubname:ABCDEF0123456789!Scotsman%2C%0AThe%2FScotland+on+Sunday+%28Scotland%29','pubname:ABCDEF0123456789!Scotsman%2C%09The%2FScotland+on+Sunday+%28Scotland%29','pubname:ABCDEF0123456789!Scotsman%2C%E2%80%A8The%2FScotland+on+Sunday+%28Scotland%29','pubname:ABCDEF0123456789!Scotsman%ZZ','pubname:ABCDEF0123456789!Scotsman%252C%2BThe','pubname:ABCDEF%3001']){const rejected=referenceCatalogue(step);assert.equal(rejected.sourceDescriptors.sources[0].browse.status,'unavailable');const {value}=await exportCatalogue(rejected);assert.equal(value.sourceDescriptors.sources[0].browse.status,'unavailable');assert.equal(value.sourceDescriptors.sources[0].browse.url,'');assert.notEqual(value.sourceDescriptors.sources[0].browse.referenceStructure?.failureCode,'none');}
});

test('long source identifiers remain rejected outside the exact row-reference namespace context',async()=>{
 const id='ABCDEF0123456789',name='Financial Times',legacy=descriptors([sourceDescriptor({browse:{status:'available',reasonCode:'native_source_url',url:'https://infoweb.newsbank.com/apps/news/browse-pub?p=UKNB&t='+encodeURIComponent('pubname:'+id+'!'+name)}})]);legacy.linkTemplate={status:'observed',reasonCode:'safe_native_source_template',path:'/apps/news/browse-pub',queryKeys:['p','t'],placeholderIndices:[0,1]};const {value}=await exportCatalogue(sourceCatalogue(legacy));assert.deepEqual(value.sourceDescriptors.sources,[]);const raw=descriptors([sourceDescriptor({location:id})]);const result=await exportCatalogue(sourceCatalogue(raw));assert.deepEqual(result.value.sourceDescriptors.sources,[]);
});

test('source-search exact selected reference can survive form action and hidden source bindings without other value exceptions',async()=>{
 const name=sourceSearch().source.name,reference='pubname:ABCDEF0123456789!'+encodeURIComponent(name).replace(/%20/g,'+'),source={...sourceSearch().source,browseURL:'https://infoweb.newsbank.com/apps/news/browse-pub?p=UKNB&t='+encodeURIComponent(reference)+'&action=browse'};const {document}=parseHTML('<html><body><h1>'+name+'</h1><form method="POST" action="https://infoweb.newsbank.com/apps/news/results?p=UKNB&amp;t%5B%5D='+encodeURIComponent(reference)+'"><input type="hidden" name="p" value="UKNB"><input type="hidden" name="t[]" value="'+reference+'"><select name="fld-base-0"><option value="title">Headline</option></select><input name="val-base-0" value="PRIVATE_QUERY"></form></body></html>'),approved=sourceSearchInspection(document,source);assert(approved);const {value,h}=await exportSourceSearch(approved);assert.deepEqual(value,approved);assert(value.page.forms[0].sourceBindings.some(binding=>binding.name==='t[]'&&binding.value===reference));assert.doesNotMatch(JSON.stringify(value),/PRIVATE_QUERY/);assert.equal(h.calls.length,1);assert.equal(h.document.querySelectorAll('#source-search-results a').length,0);
});
